    function connectRepo() {
        const repoUrl = prompt("Enter public GitHub repository URL:");
        if (!repoUrl) return;

        const repoDisplay = document.getElementById('repoName');
        const githubRegex = /^https?:\/\/(www\.)?github\.com\/[\w.-]+\/[\w.-]+\/?$/;

        if (!githubRegex.test(repoUrl.trim())) {
            repoDisplay.innerHTML = '<span style="color:#cf6679">Error: Invalid GitHub URL</span>';
            return;
        }

        repoDisplay.innerHTML = `Connected: ${repoUrl.trim().split('/').pop()}`;
        document.getElementById('repoExplorer').style.display = 'block';
    }
